import { CameraView, useCameraPermissions } from 'expo-camera';
import * as Location from 'expo-location';
import * as MediaLibrary from 'expo-media-library';
import * as Notifications from 'expo-notifications';
import * as Sharing from 'expo-sharing';
import * as SQLite from 'expo-sqlite';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Alert, Button, Platform, ScrollView, StyleSheet, Text, View } from 'react-native';

// Simple helper to open a legacy SQLite database and ensure table exists
const useVlogDatabase = () => {
  // eslint-disable-next-line import/namespace
  const db = useMemo(() => (SQLite as any).openDatabase('app.db'), []);

  useEffect(() => {
  db.transaction((tx: any) => {
      tx.executeSql(
