export default function VlogScreen() {
  const [cameraPermission, requestCameraPermission] = useCameraPermissions();
  const [mediaPermission, requestMediaPermission] = MediaLibrary.usePermissions();
  const [locationPermissionStatus, setLocationPermissionStatus] = useState<Location.PermissionStatus | null>(null);
  const [lastLocation, setLastLocation] = useState<Location.LocationObject | null>(null);
  const [lastVideoUri, setLastVideoUri] = useState<string | null>(null);
  const [dbCount, setDbCount] = useState<number>(0);
  const cameraRef = useRef<CameraView | null>(null);
  const [recording, setRecording] = useState(false);
  const [showCamera, setShowCamera] = useState(false);

  const { insertVlog, getCount } = useVlogDatabase();

  useEffect(() => {
    // Notifications: set handler to show alerts when foreground
    Notifications.setNotificationHandler({
      handleNotification: async () => ({
        shouldPlaySound: false,
        shouldShowAlert: true,
        shouldSetBadge: false,
        // Newer SDKs also support these display hints
        shouldShowBanner: true,
        shouldShowList: true,
      }) as any,
    });
  }, []);

  useEffect(() => {
    // Preload DB count
    getCount().then(setDbCount).catch(() => {});
  }, [getCount]);

  const ensurePermissions = useCallback(async () => {
    // Camera
    if (!cameraPermission?.granted) {
      await requestCameraPermission();
    }
    // Media library
    if (!mediaPermission?.granted) {
      await requestMediaPermission();
    }
    // Notifications
    const notif = await Notifications.getPermissionsAsync();
    if (notif.status !== 'granted') {
      await Notifications.requestPermissionsAsync();
    }
    // Location
    const { status } = await Location.requestForegroundPermissionsAsync();
    setLocationPermissionStatus(status);
  }, [cameraPermission?.granted, mediaPermission?.granted, requestCameraPermission, requestMediaPermission]);

  useEffect(() => {
    // Ask once on mount
    ensurePermissions();
  }, [ensurePermissions]);

  const scheduleNotification = useCallback(async () => {
    await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Vlog 提醒',
        body: '這是一個 5 秒後觸發的本機通知。',
      },
      trigger: { type: 'timeInterval', seconds: 5 },
    });
    Alert.alert('已排程', '將在 5 秒後跳出通知');
  }, []);

  const getCurrentLocation = useCallback(async () => {
    const { status } = await Location.getForegroundPermissionsAsync();
    if (status !== 'granted') {
      const request = await Location.requestForegroundPermissionsAsync();
      if (request.status !== 'granted') {
        Alert.alert('需要定位權限');
        return;
      }
    }
    const loc = await Location.getCurrentPositionAsync({});
    setLastLocation(loc);
    Alert.alert('定位成功', `緯度: ${loc.coords.latitude.toFixed(6)} 經度: ${loc.coords.longitude.toFixed(6)}`);
  }, []);

  const toggleCamera = useCallback(() => setShowCamera((v) => !v), []);

  const startStopRecording = useCallback(async () => {
    if (!cameraRef.current) return;
    if (!recording) {
      try {
        setRecording(true);
        // Using any-typed calls to keep compatibility across SDK minor API changes
        const cam: any = cameraRef.current as any;
        const video: any = await cam.recordAsync?.({ maxDuration: 30 });
        if (video?.uri) {
          // Save to media library
          const asset = await MediaLibrary.createAssetAsync(video.uri);
          setLastVideoUri(asset.uri ?? video.uri);
          // Insert DB record with optional location
          await insertVlog({
            createdAt: new Date().toISOString(),
            latitude: lastLocation?.coords.latitude ?? null,
            longitude: lastLocation?.coords.longitude ?? null,
            uri: asset.uri ?? video.uri,
          });
          const count = await getCount();
          setDbCount(count);
          Alert.alert('錄影完成', '已儲存到媒體庫並寫入資料庫');
        }
      } catch (e: any) {
        Alert.alert('錄影失敗', e?.message ?? String(e));
      } finally {
        setRecording(false);
      }
    } else {
      try {
        const cam: any = cameraRef.current as any;
        cam.stopRecording?.();
      } catch {}
      setRecording(false);
    }
  }, [recording, insertVlog, getCount, lastLocation]);

  const shareLastVideo = useCallback(async () => {
    if (!lastVideoUri) {
      Alert.alert('尚無影片可分享');
      return;
    }
    const available = await Sharing.isAvailableAsync();
    if (!available) {
      Alert.alert('分享不可用', '此平台不支援分享。');
      return;
    }
    await Sharing.shareAsync(lastVideoUri);
  }, [lastVideoUri]);

  return (
    <ScrollView contentContainerStyle={styles.container}>
      <Text style={styles.title}>Vlog 工具</Text>
      <Text style={styles.caption}>快速測試通知、定位、錄影、媒體庫、分享與 SQLite</Text>

      <View style={styles.section}>
        <Button title="5 秒後發送本機通知" onPress={scheduleNotification} />
      </View>

      <View style={styles.section}>
        <Button title="取得目前位置" onPress={getCurrentLocation} />
        {lastLocation && (
          <Text style={styles.mono}>
            lat: {lastLocation.coords.latitude.toFixed(6)} | lon: {lastLocation.coords.longitude.toFixed(6)}
          </Text>
        )}
      </View>

      {Platform.OS !== 'web' && (
        <View style={styles.section}>
          <Button title={showCamera ? '關閉相機' : '開啟相機'} onPress={toggleCamera} />
          {showCamera && (
            <View style={{ width: '100%', aspectRatio: 3 / 4, marginTop: 8, borderRadius: 12, overflow: 'hidden' }}>
              <CameraView ref={cameraRef} mode="video" facing="back" />
            </View>
          )}
          {showCamera && (
            <View style={{ marginTop: 8 }}>
              <Button title={recording ? '停止錄影' : '開始錄影'} onPress={startStopRecording} />
            </View>
          )}
        </View>
      )}

      <View style={styles.section}>
        <Button title="分享最近的影片" onPress={shareLastVideo} />
        {lastVideoUri && (
          <Text style={styles.mono} numberOfLines={1}>
            {lastVideoUri}
          </Text>
        )}
      </View>

      <View style={styles.section}>
        <Text>資料庫記錄數：{dbCount}</Text>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: {
    padding: 16,
    gap: 12,
  },
  title: {
    fontSize: 22,
    fontWeight: '600',
  },
  caption: {
    color: '#666',
  },
  section: {
    marginTop: 12,
    gap: 8,
  },
  mono: {
    fontFamily: Platform.select({ ios: 'Menlo', android: 'monospace', default: 'monospace' }),
    fontSize: 12,
