// Database helper for experience sampling data
const useVlogDatabase = () => {
  const db = useMemo(() => (SQLite as any).openDatabase('app.db'), []);

  useEffect(() => {
    db.transaction((tx: any) => {
      // Table for experience sampling records (questionnaire + vlog + GPS)
      tx.executeSql(
        `CREATE TABLE IF NOT EXISTS samples (
          id INTEGER PRIMARY KEY NOT NULL,
          created_at TEXT NOT NULL,
          sentiment INTEGER,
          activity TEXT,
          latitude REAL,
          longitude REAL,
          video_uri TEXT
        );`
      );
    });
  }, [db]);

const insertSample = useCallback(
  (payload: {
    createdAt: string;
    sentiment?: number | null;
    activity?: string | null;
    latitude?: number | null;
    longitude?: number | null;
    videoUri?: string | null;
  }) =>
    new Promise<void>((resolve, reject) => {
      db.transaction(
        (tx: any) => {
          tx.executeSql(
            'INSERT INTO samples (created_at, sentiment, activity, latitude, longitude, video_uri) VALUES (?,?,?,?,?,?);',
            [
              payload.createdAt,
              payload.sentiment ?? null,
              payload.activity ?? null,
              payload.latitude ?? null,
              payload.longitude ?? null,
              payload.videoUri ?? null,
            ]
          );
        },
        (err: any) => reject(err),
        () => resolve()
      );
    }),
  [db]
);

  const getAllSamples = useCallback(
    () =>
      new Promise<any[]>((resolve, reject) => {
        db.transaction(
          (tx: any) => {
            tx.executeSql(
              'SELECT * FROM samples ORDER BY created_at DESC;',
              [],
              (_: any, result: any) => {
                const rows = [];
                for (let i = 0; i < result.rows.length; i++) {
                  rows.push(result.rows.item(i));
                }
                resolve(rows);
              }
            );
          },
          (err: any) => reject(err)
        );
      }),
    [db]
  );

  return { insertSample, getCount, getAllSamples };
};

section: {
  marginTop: 12,
  gap: 8,
},
label: {
