export const useSamplingDatabase = () => {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const SQLite = require('expo-sqlite');
  const db = (SQLite as any).openDatabase('app.db');

  db.transaction((tx: any) => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS samples (
        id INTEGER PRIMARY KEY NOT NULL,
        created_at TEXT NOT NULL,
        sentiment INTEGER,
        activity TEXT,
        latitude REAL,
        longitude REAL,
        video_uri TEXT
      );`
    );
  });

  const insertSample = (payload: SampleRow) =>
    new Promise<void>((resolve, reject) => {
      db.transaction(
        (tx: any) => {
          tx.executeSql(
            'INSERT INTO samples (created_at, sentiment, activity, latitude, longitude, video_uri) VALUES (?,?,?,?,?,?);',
            [
              payload.created_at ?? payload.createdAt ?? new Date().toISOString(),
              payload.sentiment ?? null,
              payload.activity ?? null,
              payload.latitude ?? null,
              payload.longitude ?? null,
              payload.video_uri ?? null,
            ]
          );
        },
        (err: any) => reject(err),
        () => resolve()
      );
    });

  const getCount = () =>
    new Promise<number>((resolve, reject) => {
      db.transaction(
        (tx: any) => {
          tx.executeSql(
            'SELECT COUNT(*) as count FROM samples;',
            [],
            (_: any, result: any) => resolve((result.rows.item(0) as any).count as number)
          );
        },
        (err: any) => reject(err)
      );
    });

  const getAllSamples = () =>
    new Promise<any[]>((resolve, reject) => {
      db.transaction(
        (tx: any) => {
          tx.executeSql(
            'SELECT * FROM samples ORDER BY created_at DESC;',
            [],
            (_: any, result: any) => {
              const rows = [];
              for (let i = 0; i < result.rows.length; i++) {
                rows.push(result.rows.item(i));
              }
              resolve(rows);
            }
          );
        },
        (err: any) => reject(err)
      );
    });

  return { insertSample, getCount, getAllSamples };
};

